use std::io::{self, BufRead, BufReader, Write, BufWriter};
use std::fs::File;
use std::path::Path;
use clap::Parser;
use regex::Regex;

/// hck is a small command-line utility similar to cut(1) that splits input lines on a 
/// delimiter and outputs selected fields.
#[derive(Parser, Debug)]
#[command(
    name = "executable",
    about = "* `delimiter` is a regex by default and a fixed substring with `-L` * `header-fields` allows for specifying a literal or a regex to match header names to select columns * both `header-fields` and `fields` order dictate the order of the output columns * input files (not stdin) are automatically compressed * the output delimiter can specified with `-D`\n\n## Selection by headers\n\nInstead of specifying fields to output by index ranges (i.e `1-2,4-`), you can specify a regex or string literal to select a headered column to output with the `-F` option. By default `-F` options are treated as string literals. To treat them as regexs add the `-r` flag.\n\n## Ordering of outputs\n\n*Values are written only once*. So for a `fields` value of `4-,1,5-8`, which translates to \"print columns 4 through the end and then the last column and then columns 5 through 8\", columns 5-8 won't be printed again because they were already consumed by the `4-` range.\n\nIf `field-headers` is used as a regex then the headers will be be grouped together in groups that all matched the same regex, and in the order of the regex as specified on the CLI.",
    version = "hck git:23bebe8-modified",
    long_version = "hck git:23bebe8-modified",
)]
struct Args {
    /// Input files to parse, defaults to stdin.
    /// 
    /// If a file has a recognizable file extension indicating that it is compressed, and a local binary to perform decompression is found, decompression will occur automagically. This requires with `-z`.
    #[arg(value_name = "INPUT")]
