                                combined.push(f_idx);
                                seen.insert(f_idx);
                            }
                        }
                    }

                    let mut first = true;
                    for idx in &combined {
                        if !first { write!(writer, "{}", output_delim)?; }
                        write!(writer, "{}", header_parts[*idx])?;
                        first = false;
                    }
                    writeln!(writer)?;
                } else {
                    // Pure -F selection
                    let mut first = true;
                    for group in hfi {
                        for &idx in group {
                            if excl.contains(&(idx+1)) { continue; }
                            if !first { write!(writer, "{}", output_delim)?; }
                            write!(writer, "{}", header_parts[idx])?;
