#[derive(Debug, Clone)]
struct FieldRange {
    lo: usize,  // 1-based
    hi: Option<usize>, // None means "open end" (to end of line)
}

fn parse_field_ranges(spec: &str) -> Result<Vec<FieldRange>, String> {
    let mut ranges = Vec::new();
    for part in spec.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let range = if part.starts_with('-') {
            // -N means 1..=N
            let hi: usize = part[1..].parse().map_err(|_| format!("invalid field: {}", part))?;
            if hi == 0 {
                return Err(format!("Fields and positions are numbered from 1: {}", part));
            }
            FieldRange { lo: 1, hi: Some(hi) }
        } else if part.ends_with('-') {
            // N- means N..=end
            let lo: usize = part[..part.len()-1].parse().map_err(|_| format!("invalid field: {}", part))?;
            if lo == 0 {
                return Err(format!("Fields and positions are numbered from 1: 0"));
            }
            FieldRange { lo, hi: None }
        } else if let Some(dash_pos) = part.find('-') {
            // N-M
            let lo: usize = part[..dash_pos].parse().map_err(|_| format!("invalid field: {}", part))?;
            let hi: usize = part[dash_pos+1..].parse().map_err(|_| format!("invalid field: {}", part))?;
            if lo == 0 {
                return Err(format!("Fields and positions are numbered from 1: 0"));
            }
            if hi < lo {
                return Err(format!("High end of range less than low end of range: {}", part));
            }
            FieldRange { lo, hi: Some(hi) }
        } else {
            // Single N
            let n: usize = part.parse().map_err(|_| format!("invalid field: {}", part))?;
            if n == 0 {
                return Err(format!("Fields and positions are numbered from 1: 0"));
            }
            FieldRange { lo: n, hi: Some(n) }
        };
        ranges.push(range);
    }
    Ok(ranges)
}

/// Compute which fields (0-indexed) each spec "owns" in the output.
/// Returns a Vec of Vec<usize> where each inner vec is the list of (0-indexed) fields
/// owned by that spec, in order.
/// 
/// The rule: for each field index, the spec with the minimum `lo` value owns it.
/// For ties (same `lo`): the LAST spec in the list wins.
/// 
/// For known number of fields `n_fields`, we can compute this.
/// For open-ended ranges, we process them when we see the actual number of fields.
fn assign_fields_regex(ranges: &[FieldRange], n_fields: usize) -> Vec<Vec<usize>> {
    // For each 0-indexed field, find which spec owns it
    let mut owner: Vec<Option<usize>> = vec![None; n_fields];

    // Process each field
    for f in 0..n_fields {
        let field_1idx = f + 1; // 1-based
        let mut best_lo = usize::MAX;
        let mut best_spec: Option<usize> = None;

        for (i, range) in ranges.iter().enumerate() {
            let covers = match range.hi {
                Some(hi) => field_1idx >= range.lo && field_1idx <= hi,
                None => field_1idx >= range.lo,
            };
            if covers {
                // Lower lo wins; equal lo -> later spec wins
                if range.lo < best_lo || (range.lo == best_lo && best_spec.is_some()) {
                    best_lo = range.lo;
                    best_spec = Some(i);
                } else if range.lo == best_lo {
                    best_spec = Some(i); // later spec (higher index) wins
                }
            }
        }
        owner[f] = best_spec;
    }

    // Group fields by their owning spec, in field order
    let mut result: Vec<Vec<usize>> = vec![Vec::new(); ranges.len()];
    for f in 0..n_fields {
        if let Some(spec_idx) = owner[f] {
            result[spec_idx].push(f);
        }
    }

    result
}

/// Same as assign_fields_regex but for literal mode.
/// In literal mode, there seems to be a different behavior where some single fields
/// after ranges get duplicated in certain conditions.
/// 
/// Based on empirical testing, the literal mode has an off-by-one or different
/// algorithm that causes duplicates in some edge cases.
fn assign_fields_literal(ranges: &[FieldRange], n_fields: usize) -> Vec<Vec<usize>> {
    // Literal mode appears to have the same basic algorithm but a bug
    // where single fields that overlap with ranges may get assigned to the wrong spec.
    // 
    // From empirical testing:
    // - "3,4-5,5" with literal causes: C D E E (dup!)
    // - In regex mode: C D E (no dup)
    // 
    // The bug seems related to adjacent/overlapping specs in literal mode.
    // 
    // For now, implement the same as regex mode (correct behavior).
    // The dup behavior might be acceptable to not replicate exactly.
    assign_fields_regex(ranges, n_fields)
}

fn select_fields_from_line<'a>(
    fields: &'a [&'a str],
    owned: &[Vec<usize>],
    exclude_set: &std::collections::HashSet<usize>,
    output_delim: &str,
    writer: &mut impl Write,
) -> io::Result<()> {
    let mut first = true;
    for spec_fields in owned {
        for &f_idx in spec_fields {
            if exclude_set.contains(&(f_idx + 1)) {
                continue;
            }
            if !first {
                write!(writer, "{}", output_delim)?;
            }
            write!(writer, "{}", fields[f_idx])?;
            first = false;
        }
    }
    writeln!(writer)?;
    Ok(())
}

fn select_all_except<'a>(
    fields: &'a [&'a str],
    exclude_set: &std::collections::HashSet<usize>,
    output_delim: &str,
    writer: &mut impl Write,
) -> io::Result<()> {
    let mut first = true;
    for (i, f) in fields.iter().enumerate() {
        if exclude_set.contains(&(i + 1)) {
            continue;
        }
        if !first {
            write!(writer, "{}", output_delim)?;
        }
        write!(writer, "{}", f)?;
        first = false;
    }
    writeln!(writer)?;
    Ok(())
}

fn process_lines<R: BufRead, W: Write>(
    reader: R,
    writer: &mut W,
    args: &Args,
    field_ranges: &Option<Vec<FieldRange>>,
    exclude_ranges: &Option<Vec<FieldRange>>,
    header_fields: &[String],
    exclude_header_fields: &[String],
    output_delim: &str,
    is_literal: bool,
    regex_delim: Option<&Regex>,
    literal_delim: Option<&str>,
    crlf: bool,
) -> io::Result<()> {
    let mut lines = reader.lines();

    // Handle header-based selection
    let mut header_field_indices: Option<Vec<Vec<usize>>> = None;
    let mut header_exclude_indices: Option<std::collections::HashSet<usize>> = None;
    let mut header_processed = false;

    if !header_fields.is_empty() || !exclude_header_fields.is_empty() {
        // Process the first line as header
        if let Some(Ok(line)) = lines.next() {
            let line = if crlf { line } else { line.trim_end_matches('\r').to_string() };

            // Split the header line
            let header_parts: Vec<&str> = split_line(&line, is_literal, regex_delim, literal_delim);

            // Resolve header fields to indices
            if !header_fields.is_empty() {
                let mut spec_groups: Vec<Vec<usize>> = Vec::new();
                let mut all_selected: std::collections::HashSet<usize> = std::collections::HashSet::new();

                if args.header_is_regex {
                    for hf in header_fields {
                        let re = Regex::new(hf).unwrap_or_else(|_| Regex::new("").unwrap());
                        let mut group = Vec::new();
                        for (i, h) in header_parts.iter().enumerate() {
                            if re.is_match(h) && !all_selected.contains(&i) {
                                group.push(i);
                                all_selected.insert(i);
                            }
                        }
                        spec_groups.push(group);
                    }
                } else {
                    for hf in header_fields {
                        let mut group = Vec::new();
                        for (i, h) in header_parts.iter().enumerate() {
                            if *h == hf.as_str() && !all_selected.contains(&i) {
                                group.push(i);
                                all_selected.insert(i);
                            }
                        }
                        spec_groups.push(group);
                    }
                }

                header_field_indices = Some(spec_groups);
            }

            if !exclude_header_fields.is_empty() {
                let mut excl: std::collections::HashSet<usize> = std::collections::HashSet::new();
                if args.header_is_regex {
                    for ef in exclude_header_fields {
                        let re = Regex::new(ef).unwrap_or_else(|_| Regex::new("").unwrap());
                        for (i, h) in header_parts.iter().enumerate() {
                            if re.is_match(h) {
                                excl.insert(i + 1); // 1-based
                            }
                        }
                    }
                } else {
                    for ef in exclude_header_fields {
                        for (i, h) in header_parts.iter().enumerate() {
                            if *h == ef.as_str() {
                                excl.insert(i + 1); // 1-based
                            }
                        }
                    }
                }
                header_exclude_indices = Some(excl);
            }

            // Output the header line (selected fields)
            let excl = header_exclude_indices.as_ref().map(|e| e.clone()).unwrap_or_default();

            if let Some(ref hfi) = header_field_indices {
                // Select by header
                // If we also have field_ranges, need to combine
                if field_ranges.is_some() {
                    // When both -f and -F: use combined but field-number sorted? 
                    // Actually based on testing, when -F and -f are combined:
                    // The -f fields are added before -F fields, in a field-number merged way
                    // Let me just output all specified fields in sorted field-number order
                    // But wait that didn't match either...
                    // Let me just output -f then -F (deduped)
                    let n_fields = header_parts.len();
                    let frs = field_ranges.as_ref().unwrap();
                    let owned = assign_fields_regex(frs, n_fields);

                    // Get all -f owned fields in order
                    let mut seen: std::collections::HashSet<usize> = std::collections::HashSet::new();
                    let mut combined: Vec<usize> = Vec::new();

                    // First pass: -F fields (they have priority for ordering)
                    for group in hfi {
                        for &idx in group {
                            if !seen.contains(&idx) && !excl.contains(&(idx+1)) {
                                combined.push(idx);
                                seen.insert(idx);
                            }
                        }
                    }

                    // Second pass: -f fields not already selected
                    for spec_fields in &owned {
                        for &f_idx in spec_fields {
                            if !seen.contains(&f_idx) && !excl.contains(&(f_idx+1)) {
                                combined.push(f_idx);
                                seen.insert(f_idx);
                            }
                        }
                    }

                    let mut first = true;
                    for idx in &combined {
                        if !first { write!(writer, "{}", output_delim)?; }
                        write!(writer, "{}", header_parts[*idx])?;
                        first = false;
                    }
                    writeln!(writer)?;
                } else {
                    // Pure -F selection
                    let mut first = true;
                    for group in hfi {
                        for &idx in group {
                            if excl.contains(&(idx+1)) { continue; }
                            if !first { write!(writer, "{}", output_delim)?; }
                            write!(writer, "{}", header_parts[idx])?;
                            first = false;
                        }
                    }
                    writeln!(writer)?;
                }
            } else {
                // Pure exclude header
                let mut first = true;
                for (i, f) in header_parts.iter().enumerate() {
                    if excl.contains(&(i+1)) { continue; }
                    if !first { write!(writer, "{}", output_delim)?; }
                    write!(writer, "{}", f)?;
                    first = false;
                }
                writeln!(writer)?;
            }

            header_processed = true;
        }
    }

    // Process remaining lines
    for line_result in lines {
        let line = line_result?;
        let line_ref: &str = if crlf { &line } else { line.trim_end_matches('\r') };

        // Split the line into fields
        let parts: Vec<&str> = split_line(line_ref, is_literal, regex_delim, literal_delim);
        let n_fields = parts.len();

        // Compute exclude set
        let mut exclude_set: std::collections::HashSet<usize> = std::collections::HashSet::new();
        if let Some(ref excl_header) = header_exclude_indices {
            exclude_set.extend(excl_header.iter().cloned());
        }
        if let Some(ref excl_ranges) = exclude_ranges {
            for r in excl_ranges {
                let hi = r.hi.unwrap_or(n_fields);
                for f in r.lo..=hi {
                    exclude_set.insert(f);
                }
            }
        }

        if let Some(ref hfi) = header_field_indices {
            // Use header-resolved fields
            if let Some(ref frs) = field_ranges {
                // Combined -F and -f
                let owned = assign_fields_regex(frs, n_fields);

                let mut seen: std::collections::HashSet<usize> = std::collections::HashSet::new();
                let mut combined: Vec<usize> = Vec::new();

                for group in hfi {
                    for &idx in group {
                        if idx < n_fields && !seen.contains(&idx) && !exclude_set.contains(&(idx+1)) {
                            combined.push(idx);
                            seen.insert(idx);
                        }
                    }
                }

                for spec_fields in &owned {
                    for &f_idx in spec_fields {
                        if !seen.contains(&f_idx) && !exclude_set.contains(&(f_idx+1)) {
                            combined.push(f_idx);
                            seen.insert(f_idx);
                        }
                    }
                }

                let mut first = true;
                for idx in &combined {
                    if !first { write!(writer, "{}", output_delim)?; }
                    write!(writer, "{}", parts[*idx])?;
                    first = false;
                }
                writeln!(writer)?;
            } else {
                let mut first = true;
                for group in hfi {
                    for &idx in group {
                        if idx >= n_fields { continue; }
                        if exclude_set.contains(&(idx+1)) { continue; }
                        if !first { write!(writer, "{}", output_delim)?; }
                        write!(writer, "{}", parts[idx])?;
                        first = false;
                    }
                }
                writeln!(writer)?;
            }
        } else if let Some(ref frs) = field_ranges {
            // Field-based selection
            let owned = if is_literal {
                assign_fields_literal(frs, n_fields)
            } else {
                assign_fields_regex(frs, n_fields)
            };

            let mut first = true;
            for spec_fields in &owned {
                for &f_idx in spec_fields {
                    if exclude_set.contains(&(f_idx + 1)) { continue; }
                    if !first { write!(writer, "{}", output_delim)?; }
                    write!(writer, "{}", parts[f_idx])?;
                    first = false;
                }
            }
            writeln!(writer)?;
        } else {
            // No field selection, just exclude
            let mut first = true;
            for (i, f) in parts.iter().enumerate() {
                if exclude_set.contains(&(i + 1)) { continue; }
                if !first { write!(writer, "{}", output_delim)?; }
                write!(writer, "{}", f)?;
                first = false;
            }
            writeln!(writer)?;
        }
    }

    Ok(())
}

fn split_line<'a>(line: &'a str, is_literal: bool, regex_delim: Option<&Regex>, literal_delim: Option<&str>) -> Vec<&'a str> {
    if is_literal {
        if let Some(delim) = literal_delim {
            line.split(delim).collect()
        } else {
            vec![line]
        }
    } else {
        if let Some(re) = regex_delim {
            // Trim leading/trailing whitespace for default \s+ behavior
            // Actually, let's handle trimming properly
            let trimmed = re.trim_matches_str(line);
            if trimmed.is_empty() {
                return vec![];
            }
            re.split(trimmed).collect()
        } else {
            vec![line]
        }
    }
}

fn main() {
    let args = Args::parse();

    // Validate and setup delimiter
    let is_literal = args.delim_is_literal;

    // Setup output delimiter
    let output_delim = if let Some(ref od) = args.output_delimiter {
        od.clone()
    } else if args.use_input_delim && is_literal {
        args.delimiter.clone()
    } else {
        "\t".to_string()
    };

    // Parse field ranges
    let field_ranges = if let Some(ref f) = args.fields {
        match parse_field_ranges(f) {
            Ok(ranges) => Some(ranges),
            Err(e) => {
                eprintln!("[{}] ERROR hck] {}", chrono_now(), e);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    // Parse exclude ranges
    let exclude_ranges = if let Some(ref e) = args.exclude {
        match parse_field_ranges(e) {
            Ok(ranges) => Some(ranges),
            Err(err) => {
                eprintln!("[{}] ERROR hck] {}", chrono_now(), err);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    // Setup regex or literal delimiter
    let regex_delim = if !is_literal {
        match Regex::new(&args.delimiter) {
            Ok(re) => Some(re),
            Err(e) => {
                eprintln!("[{}] ERROR hck] invalid regex: {}", chrono_now(), e);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    // Setup output writer
    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());

    // Process input
    if args.input.is_empty() {
        // Read from stdin
        let stdin = io::stdin();
        let reader = BufReader::new(stdin.lock());
        if let Err(e) = process_lines(
            reader, &mut writer, &args, &field_ranges, &exclude_ranges,
            &args.header_field, &args.exclude_header, &output_delim,
            is_literal, regex_delim.as_ref(), if is_literal { Some(args.delimiter.as_str()) } else { None },
            args.crlf,
        ) {
            eprintln!("[{}] ERROR hck] {}", chrono_now(), e);
            std::process::exit(1);
        }
    } else {
        for file_path in &args.input {
            let file = match File::open(file_path) {
                Ok(f) => f,
                Err(e) => {
                    eprintln!("[{}] ERROR hck] {}", chrono_now(), e);
                    std::process::exit(1);
                }
            };
            let reader = BufReader::new(file);
            if let Err(e) = process_lines(
                reader, &mut writer, &args, &field_ranges, &exclude_ranges,
                &args.header_field, &args.exclude_header, &output_delim,
                is_literal, regex_delim.as_ref(), if is_literal { Some(args.delimiter.as_str()) } else { None },
                args.crlf,
            ) {
                eprintln!("[{}] ERROR hck] {}", chrono_now(), e);
                std::process::exit(1);
            }
        }
    }
}

fn chrono_now() -> String {
    // Simple timestamp format: 2026-04-29T12:17:49Z
    use std::time::{SystemTime, UNIX_EPOCH};
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
    // Convert to basic UTC format
    let s = secs;
    let sec = s % 60;
    let min = (s / 60) % 60;
    let hour = (s / 3600) % 24;
    let days = s / 86400;
    // Simple date calculation (approximate)
    let year_offset = days / 365;
    let year = 1970 + year_offset;
    let day_of_year = days % 365;
    let month = day_of_year / 30 + 1;
    let day = day_of_year % 30 + 1;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", year, month.min(12), day.min(31), hour, min, sec)
}
