def parse_field_ranges(spec):
    """Parse field ranges like '1,2-4,5-' into list of (lo, hi) where hi=None means open end."""
    ranges = []
    for part in spec.split(','):
        part = part.strip()
        if not part:
            continue
        if part.startswith('-'):
            # -N means 1..N
            hi = int(part[1:])
            if hi == 0:
                raise ValueError(f"Fields and positions are numbered from 1: 0")
            ranges.append((1, hi))
        elif part.endswith('-'):
            # N- means N..end
            lo = int(part[:-1])
            if lo == 0:
                raise ValueError(f"Fields and positions are numbered from 1: 0")
            ranges.append((lo, None))
        elif '-' in part:
            # N-M
            dash_pos = part.index('-')
            lo = int(part[:dash_pos])
            hi = int(part[dash_pos+1:])
            if lo == 0:
                raise ValueError(f"Fields and positions are numbered from 1: 0")
            if hi < lo:
                raise ValueError(f"High end of range less than low end of range: {part}")
            ranges.append((lo, hi))
        else:
            n = int(part)
            if n == 0:
                raise ValueError(f"Fields and positions are numbered from 1: 0")
            ranges.append((n, n))
    return ranges

