    header_field_indices = None
    header_exclude_indices = None

    def open_input(path):
        if args.try_decompress:
            ext = os.path.splitext(path)[1].lower()
            if ext == '.gz':
                import gzip
                return gzip.open(path, 'rt')
            elif ext == '.bz2':
                import bz2
                return bz2.open(path, 'rt')
            elif ext == '.xz':
                import lzma
                return lzma.open(path, 'rt')
        return open(path, 'r')

    def resolve_headers(first_line_parts):
        nonlocal header_field_indices, header_exclude_indices

        if args.header_field:
            spec_groups = []
            all_selected = set()

            if args.header_is_regex:
                for hf in args.header_field:
                    try:
                        hf_re = re.compile(hf)
                    except re.error:
                        hf_re = re.compile('')
                    group = []
                    for i, h in enumerate(first_line_parts):
                        if hf_re.search(h) and i not in all_selected:
                            group.append(i)
                            all_selected.add(i)
                    spec_groups.append(group)
            else:
                for hf in args.header_field:
                    group = []
                    for i, h in enumerate(first_line_parts):
                        if h == hf and i not in all_selected:
                            group.append(i)
                            all_selected.add(i)
                    spec_groups.append(group)

            header_field_indices = spec_groups

        if args.exclude_header:
            excl = set()
            if args.header_is_regex:
                for ef in args.exclude_header:
                    try:
                        ef_re = re.compile(ef)
                    except re.error:
                        ef_re = re.compile('')
                    for i, h in enumerate(first_line_parts):
                        if ef_re.search(h):
                            excl.add(i + 1)  # 1-based
            else:
                for ef in args.exclude_header:
                    for i, h in enumerate(first_line_parts):
                        if h == ef:
                            excl.add(i + 1)  # 1-based
            header_exclude_indices = excl

    need_header_resolution = bool(args.header_field or args.exclude_header)

    def process_file(f, is_first_file=False):
        nonlocal header_field_indices, header_exclude_indices

        lines = iter(f)

        if need_header_resolution and is_first_file:
            # Process header line
            try:
                header_line = next(lines)
            except StopIteration:
                return

            crlf = args.crlf
            if not crlf:
                header_line_stripped = header_line.rstrip('\n').rstrip('\r')
            else:
                header_line_stripped = header_line.rstrip('\n')

            if is_literal:
                header_parts = header_line_stripped.split(literal_delim)
            else:
                if args.delimiter == r'\s+':
                    stripped = header_line_stripped.strip()
                    if not stripped:
                        header_parts = []
                    else:
                        header_parts = delim_re.split(stripped)
                else:
                    header_parts = delim_re.split(header_line_stripped)

            resolve_headers(header_parts)

            # Output header line
            excl = header_exclude_indices or set()

            if header_field_indices is not None:
                if field_ranges:
                    # Combined -F and -f
                    n = len(header_parts)
                    owned = assign_fields(field_ranges, n)
                    seen = set()
                    combined = []

                    for group in header_field_indices:
                        for idx in group:
                            if idx < n and idx not in seen and (idx+1) not in excl:
                                combined.append(idx)
                                seen.add(idx)

                    for spec_fields in owned:
                        for f_idx in spec_fields:
                            if f_idx not in seen and (f_idx+1) not in excl:
                                combined.append(f_idx)
                                seen.add(f_idx)

                    output_parts = [header_parts[i] for i in combined if i < n]
                else:
                    output_parts = []
                    for group in header_field_indices:
                        for idx in group:
                            if idx < len(header_parts) and (idx+1) not in excl:
                                output_parts.append(header_parts[idx])
            else:
                # Pure exclude header
                output_parts = [p for i, p in enumerate(header_parts) if (i+1) not in excl]

            if crlf:
                writer.write(output_delim.join(output_parts) + '\r\n')
            else:
                writer.write(output_delim.join(output_parts) + '\n')

        # Process data lines
        process_stream(lines, args, field_ranges, exclude_ranges, header_field_indices,
                      header_exclude_indices, output_delim, is_literal, delim_re, literal_delim,
                      writer, False)

    if not args.input:
        # Read from stdin
        process_file(sys.stdin, is_first_file=True)
    else:
        for i, file_path in enumerate(args.input):
            try:
                with open_input(file_path) as f:
                    process_file(f, is_first_file=(i == 0))
            except IOError as e:
                error(str(e))
                sys.exit(1)

    if args.output:
        out_file.close()

